KV(a,b,c,d){return""+a+"% \ud655\ub960\ub85c "+b+" "+c+" \ub3d9\uc548 [[\ucd9c\ud608]]\uc2dc\ucf1c\uc694 (\ud134\ub9c8\ub2e4 \uc0ac\uc6a9\uc790 <atk>\uacf5\uaca9\ub825</atk>\uc758 "+d+"% \ud53c\ud574)."},
Lg(a,b){return a+" "+b+" \ub3d9\uc548 [[\ubc18\uc0ac]]\ub97c \uc918\uc694: \uc801\uc774 \uac70\ub294 \ub2e4\uc74c \uc57d\ud654 \ud6a8\uacfc\uac00 \uadf8 \uc801\uc5d0\uac8c \ub418\ub3cc\uc544\uac00\uc694."},
L7(a,b){return a+" [[\ubc29\ud574]]\ud574\uc694: \ucfe8\ud0c0\uc784\uc774 \uc788\ub294 \uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 "+b+" \ub354 \uac78\ub824\uc694."},
L8(a,b,c){return""+a+"% \ud655\ub960\ub85c "+b+" [[\ubc29\ud574]]\ud574\uc694: \ucfe8\ud0c0\uc784\uc774 \uc788\ub294 \uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 "+c+" \ub354 \uac78\ub824\uc694."},
L9(a,b,c){return a+" "+b+" \ub3d9\uc548 [[\uc0dd\uba85\uc758 \ubd88\uc528]]\ub97c \uc918\uc694: \uc4f0\ub7ec\uc838\ub3c4 \ubc14\ub85c \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+c+"%\ub85c \uc77c\uc5b4\ub098\uc694 (\uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88)."},
KM(a){return"\uce58\uba85\ud0c0\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \ud55c \ubc88 \ub354 \uacf5\uaca9\ud574\uc694 (\ucd5c\ub300 "+a+"\ud68c \ucd94\uac00)."},
y9(a){return"\uce58\uba85\ud0c0 \uc5f0\uc1c4 +"+a},
SE(a){return"\uc774 Ovaling\uc758 <fx:heal>\ud68c\ubcf5</fx>\uacfc <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc774 "+a+"% \uac15\ud574\uc838\uc694."},
SL(a){return"\ubaa8\ub4e0 \uc804\ud22c\uac00 \uc2dc\uc791\ub420 \ub54c \ud300 \uc804\uccb4\uac00 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+a+"% <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc744 \ubc1b\uc544\uc694."},
Sy(a){return"\uc790\uc2e0\uc758 \uce58\uba85\ud0c0\uac00 \ub300\uc0c1\uc744 2\ud134 \ub3d9\uc548 <fx:bleed>\ucd9c\ud608</fx>\uc2dc\ucf1c\uc694 (\ud134\ub9c8\ub2e4 \uc790\uc2e0 <atk>\uacf5\uaca9\ub825</atk>\uc758 "+a+"% \ud53c\ud574)."},
SD(a){return"<hp>\uccb4\ub825</hp>\uc774 30% \ubbf8\ub9cc\uc778 \ub300\uc0c1\uc5d0\uac8c \ud53c\ud574 +"+a+"%."},
gX9(){return"\uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c\ub9c8\ub2e4 \ud53c\ud574\ub97c \uc785\uc5b4\uc694. \ud53c\ud574\ub294 \uacf5\uaca9\ud55c \ucabd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc694."},
gXa(){return"\ucd9c\ud608 \uc0c1\ud0dc\uc778 Ovaling\uc740 \uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c\ub9c8\ub2e4 \ucd9c\ud608\uc744 \uac74 \ucabd <atk>\uacf5\uaca9\ub825</atk>\uc758 \uc77c\ubd80\ub9cc\ud07c \ud53c\ud574\ub97c \uc785\uc5b4\uc694. \ub3c5\uc740 \ub300\uc0c1\uc758 <hp>\uccb4\ub825</hp>\uc5d0, \ucd9c\ud608\uc740 \uacf5\uaca9\ud55c \ucabd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc694. \ucd9c\ud608\uc740 <def>\ubc29\uc5b4\ub825</def>\uc744 \ubb34\uc2dc\ud558\uace0, \ub3c5\uacfc \ud568\uaed8 \uac78\ub9ac\uba70, \ub3c5\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc801\uc5d0\uac8c\ub3c4 \ud1b5\ud574\uc694. \ub3c5\uc73c\ub85c \uce58\uc9c0 \uc54a\uc544\uc694."},
gXJ(){return"\ub2e4\uc74c \uc57d\ud654 \ud6a8\uacfc\ub97c \uc801\uc5d0\uac8c \ub418\ub3cc\ub824\uc694."},
gXK(){return"\ubc18\uc0ac\uac00 \uc9c0\uc18d\ub418\ub294 \ub3d9\uc548 \uc801\uc774 \uc774 Ovaling\uc5d0\uac8c \uac70\ub294 \ub2e4\uc74c \uc57d\ud654 \ud6a8\uacfc\ub294 \ud295\uaca8 \ub098\uac00 \uadf8 \uc801\uc5d0\uac8c \uac78\ub824\uc694. \uadf8 \ud6c4 \ubc18\uc0ac\ub294 \uc0ac\ub77c\uc838\uc694. \uc57d\ud654 \ucc28\ub2e8\uacfc \uc800\ud56d\uc774 \uba3c\uc800 \uc801\uc6a9\ub3fc\uc694."},
gXz(){return"\uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 \ub354 \uc624\ub798 \uac78\ub824\uc694."},
